// Prismatic Dash Plushie Mascot
// A 3D Dash hummingbird sculpted from tinted, very transparent glass floating
// on OLED black with thin-film iridescence, spotted specular highlights, and amber beak.

// ============================================================================
// --- CONFIGURATION CONSTANTS (Tweak these to customize shader behavior) -----
// ============================================================================

// --- Glass Transparency & Surface Look ---
#define GLASS_TRANSPARENCY      0.82    // 0.0 = solid crystal, 0.95 = ultra-clear transparent glass
#define GLASS_REFRACT_FACTOR    0.06    // Subtle internal refraction bend
#define GLASS_TINT_INTENSITY    0.70    // Saturation and depth of Dash cyan glass
#define FRESNEL_POWER           3.0     // View-angle reflection power (concentrates on rims)

// --- Dash Palette Tints ---
#define DASH_CYAN_TINT          vec3(0.10, 0.68, 0.98) // Iconic Dash blue/cyan plumage
#define BEAK_AMBER_TINT         vec3(1.00, 0.62, 0.12) // Translucent amber glass beak & feet
#define EYE_WHITE_TINT          vec3(0.95, 0.98, 1.00) // Clear crystalline eye sclera
#define EYE_PUPIL_TINT          vec3(0.04, 0.07, 0.16) // Deep obsidian pupil crystal
#define CHEST_CRYSTAL_TINT      vec3(0.88, 0.96, 1.00) // Lighter belly/mask patch

// --- Highlight & Specular Settings (Spotted Highlights) ---
#define HIGHLIGHT_INTENSITY     3.6     // Peak brightness of specular spots
#define HIGHLIGHT_SHARPNESS     85.0    // Specular tightness / glossiness (higher = tighter spots)
#define HIGHLIGHT_SPOTTEDNESS   1.20    // Contrast / concentration of circular specular spots
#define HIGHLIGHT_DISPERSION    0.12    // Chromatic dispersion (rainbow split in specular spot)
#define RIM_GLINT_INTENSITY     1.40    // Elegant razor edge reflections along glass curves

// --- Iridescence & Animation ---
#define IRID_FLOW_SPEED         0.22    // Speed of spectral thin-film wave flow
#define IRID_SPECTRUM_FREQ      0.40    // Density/frequency of rainbow cycles
#define IRID_FRINGE_INTENSITY   0.14    // Thin-film optical interference fringe strength

// --- 3D Mascot Dimensions & Motion ---
#define DASH_SCALE              1.12    // Viewport scale
#define DASH_FLOAT_SPEED        0.45    // Idle breathing & floating speed

// --- Background & Bloom ---
#define CORONA_BLOOM_GLOW       0.12    // Subtle luminous glass aura on OLED black
#define CORONA_FALLOFF          18.0    // Falloff rate of the background corona
// ============================================================================

mat2 rot2D(float a) {
    float c = cos(a), s = sin(a);
    return mat2(c, -s, s, c);
}

float smin(float a, float b, float k) {
    float h = max(k - abs(a - b), 0.0) / k;
    return min(a, b) - h * h * k * 0.25;
}

float sdSphere(vec3 p, float r) {
    return length(p) - r;
}

float sdEllipsoid(vec3 p, vec3 r) {
    float k0 = length(p / r);
    float k1 = length(p / (r * r));
    return k0 * (k0 - 1.0) / max(k1, 1e-4);
}

float sdCone(vec3 p, float r1, float r2, float h) {
    vec2 q = vec2(length(p.xy), p.z);
    float b = (r1 - r2) / h;
    float a = sqrt(max(0.0, 1.0 - b * b));
    float k = -q.x * b + q.y * a;
    if (k < 0.0) return length(q) - r1;
    if (k > a * h) return length(q - vec2(0.0, h)) - r2;
    return q.x * a + q.y * b - r1;
}

float sdCapsule(vec3 p, vec3 a, vec3 b, float r) {
    vec3 pa = p - a, ba = b - a;
    float h = clamp(dot(pa, ba) / dot(ba, ba), 0.0, 1.0);
    return length(pa - ba * h) - r;
}

// Dash 3D Mascot Signed Distance Function
// Returns vec4(distance, materialId, localU, localV)
vec4 mapDash(vec3 p, float time) {
    // Idle breathing and floating bob
    float floatBob = sin(time * DASH_FLOAT_SPEED * 1.5) * 0.035;
    float breathe = sin(time * DASH_FLOAT_SPEED * 2.2) * 0.012;
    p.y += floatBob;

    // Default idle pose tilt
    p.yz = rot2D(-0.06 + sin(time * DASH_FLOAT_SPEED * 0.9) * 0.02) * p.yz;
    p.xz = rot2D( 0.30 + cos(time * DASH_FLOAT_SPEED * 0.8) * 0.04) * p.xz;

    vec3 origP = p / DASH_SCALE;
    p = origP;

    float matId = 1.0; // 1 = Body (Cyan glass)

    // 1. Chubby Pear Body & Head
    float taper = 1.0 - (p.y - 0.05) * 0.20;
    vec3 bp = vec3(p.x / taper, p.y * (1.06 + breathe), p.z / taper);
    float dBody = (length(bp) - 0.74) * 0.86;

    // Belly/Chest soft patch detection
    if (p.z > 0.32 && p.y > -0.45 && p.y < 0.25 && abs(p.x) < 0.38) {
        matId = 6.0; // Lighter chest crystal
    }

    // 2. Head Tuft (3 cute feathers)
    vec3 tp = p - vec3(0.0, 0.73, 0.04);
    float tuft1 = sdCapsule(tp, vec3(0.0), vec3(0.0, 0.22, -0.10), 0.045);
    float tuft2 = sdCapsule(tp, vec3(-0.05, 0.0, 0.0), vec3(-0.11, 0.17, -0.07), 0.040);
    float tuft3 = sdCapsule(tp, vec3( 0.05, 0.0, 0.0), vec3( 0.11, 0.17, -0.07), 0.040);
    float dTuft = min(tuft1, min(tuft2, tuft3));
    dBody = smin(dBody, dTuft, 0.07);

    // 3. Wings (left & right)
    vec3 wp = vec3(abs(p.x) - 0.65, p.y + 0.02, p.z + 0.04);
    float sideSign = (p.x > 0.0) ? 1.0 : -1.0;
    wp.xy = rot2D(-0.35 * sideSign) * wp.xy;
    wp.xz = rot2D(-0.25 * sideSign) * wp.xz;
    float wingBase = sdEllipsoid(wp, vec3(0.11, 0.34, 0.24));
    float wingScallop1 = sdEllipsoid(wp + vec3(0.0, 0.15, 0.10), vec3(0.09, 0.22, 0.18));
    float wingScallop2 = sdEllipsoid(wp + vec3(0.0, -0.12, 0.08), vec3(0.09, 0.20, 0.16));
    float dWing = smin(wingBase, min(wingScallop1, wingScallop2), 0.06);
    dBody = smin(dBody, dWing, 0.08);

    // 4. Tail
    vec3 tailP = p - vec3(0.0, -0.34, -0.62);
    tailP.yz = rot2D(-0.6) * tailP.yz;
    float dTail = sdEllipsoid(tailP, vec3(0.24, 0.06, 0.32));
    dBody = smin(dBody, dTail, 0.09);

    // 5. Beak (Amber glass cone pointing forward-down)
    vec3 beakP = p - vec3(0.0, 0.06, 0.62);
    beakP.yz = rot2D(0.12) * beakP.yz;
    float dBeak = sdCone(beakP, 0.15, 0.02, 0.36);
    if (dBeak < dBody) {
        dBody = smin(dBody, dBeak, 0.03);
        if (dBeak < 0.025) {
            matId = 2.0; // Amber beak
        }
    }

    // 6. Eyes (Large round eyes with pupils)
    float symX = abs(p.x) - 0.25;
    vec3 eyePos = vec3(symX, p.y - 0.16, p.z - 0.58);
    float dEyeWhite = sdSphere(eyePos, 0.14);
    float dPupil = sdSphere(vec3(symX, p.y - 0.16, p.z - 0.67), 0.075);

    if (dPupil < dBody && dPupil < 0.015) {
        matId = 4.0; // Obsidian pupil
    } else if (dEyeWhite < dBody && dEyeWhite < 0.025) {
        matId = 3.0; // Clear eye sclera
    }

    // 7. Feet (3-toed amber bird feet)
    vec3 footP = vec3(abs(p.x) - 0.24, p.y + 0.66, p.z - 0.32);
    float toe1 = sdCapsule(footP, vec3(0.0), vec3(0.0, -0.05, 0.15), 0.038);
    float toe2 = sdCapsule(footP, vec3(0.0), vec3(-0.08, -0.05, 0.12), 0.034);
    float toe3 = sdCapsule(footP, vec3(0.0), vec3( 0.08, -0.05, 0.12), 0.034);
    float dFeet = min(toe1, min(toe2, toe3));
    if (dFeet < dBody) {
        dBody = dFeet;
        matId = 5.0; // Amber feet
    }

    return vec4(dBody * DASH_SCALE, matId, origP.x, origP.y);
}

vec3 calcNormal(vec3 p, float time) {
    vec2 e = vec2(0.0015, 0.0);
    float d = mapDash(p, time).x;
    return normalize(vec3(
        mapDash(p + e.xyy, time).x - d,
        mapDash(p + e.yxy, time).x - d,
        mapDash(p + e.yyx, time).x - d
    ));
}

// Thin-film iridescent cosine palette
vec3 spectralPalette(float phase) {
    vec3 col = 0.5 + 0.5 * cos(6.2831853 * (phase + vec3(0.00, 0.33, 0.67)));
    float fringe = sin(6.2831853 * phase * 2.5) * IRID_FRINGE_INTENSITY;
    col.r = clamp(col.r + fringe, 0.0, 1.0);
    col.g = clamp(col.g + fringe * 0.3, 0.0, 1.0);
    col.b = clamp(col.b - fringe * 0.5, 0.0, 1.0);
    return col;
}

// ACES filmic tone mapping curve
vec3 acesFilm(vec3 x) {
    float a = 2.51;
    float b = 0.03;
    float c = 2.43;
    float d = 0.59;
    float e = 0.14;
    return clamp((x * (a * x + b)) / (x * (c * x + d) + e), 0.0, 1.0);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (2.0 * fragCoord - iResolution.xy) / min(iResolution.x, iResolution.y);

    // Interactive mouse rotation
    vec2 m = iMouse.xy / iResolution.xy;
    float mouseYaw = (iMouse.z > 0.0) ? (m.x - 0.5) * 3.2 : 0.0;
    float mousePitch = (iMouse.z > 0.0) ? (m.y - 0.5) * 2.4 : 0.0;

    vec3 ro = vec3(0.0, 0.0, 3.2);
    vec3 rd = normalize(vec3(uv, -2.4));

    ro.xz = rot2D(mouseYaw) * ro.xz;
    rd.xz = rot2D(mouseYaw) * rd.xz;
    ro.yz = rot2D(mousePitch) * ro.yz;
    rd.yz = rot2D(mousePitch) * rd.yz;

    // Studio light setup: Front Key Light, Upper-Right Rim, Upper-Left Rim
    vec3 lightPos1 = vec3(0.7, 1.0, 2.1);    // Key light -> creates glossy circular spot on face
    vec3 lightPos2 = vec3(-1.8, 1.5, 0.3);   // Left rim light
    vec3 lightPos3 = vec3( 1.7, 1.3, -0.5);  // Right rim light

    // Raymarching
    float t = 0.8;
    float minD = 10.0;
    vec4 hitData = vec4(0.0);
    bool hit = false;

    for (int i = 0; i < 90; i++) {
        vec3 p = ro + t * rd;
        vec4 res = mapDash(p, iTime);
        if (res.x < minD) minD = res.x;
        if (res.x < 0.0014) {
            hit = true;
            hitData = res;
            break;
        }
        t += res.x * 0.84;
        if (t > 6.2) break;
    }

    vec3 col = vec3(0.0);

    if (hit) {
        vec3 pos = ro + t * rd;
        vec3 n = calcNormal(pos, iTime);

        float ndotv = max(dot(n, -rd), 0.0);
        float fresnel = 1.0 - ndotv;
        float fresnelPow = pow(fresnel, FRESNEL_POWER);

        // Spectral iridescent wave across curved glass surfaces
        float flow = -iTime * IRID_FLOW_SPEED;
        float phase = (hitData.z * 0.35 + hitData.w * 0.45) * IRID_SPECTRUM_FREQ + fresnel * 0.60 + flow + 0.30;
        vec3 irid = spectralPalette(phase);

        // Studio Key Light (circular/spotted specular highlight)
        vec3 l1 = normalize(lightPos1 - pos);
        float diff1 = max(dot(n, l1), 0.0);

        // Rim lights
        vec3 l2 = normalize(lightPos2 - pos);
        vec3 l3 = normalize(lightPos3 - pos);

        vec3 ref = reflect(rd, n);
        float refl1 = max(dot(ref, l1), 0.0);
        float refl2 = max(dot(ref, l2), 0.0);
        float refl3 = max(dot(ref, l3), 0.0);

        // Highlight spottedness: localized glossy spots
        float spotWave = sin((hitData.z * 2.0 - hitData.w * 1.5) * 3.0 + flow * 0.5) * 0.5 + 0.5;
        float spotFactor = pow(spotWave, 2.0);
        float spotMod = (1.0 - HIGHLIGHT_SPOTTEDNESS * 0.3) + HIGHLIGHT_SPOTTEDNESS * spotFactor * 0.6;

        // Chromatic dispersion for R, G, B in specular highlights
        float expR = HIGHLIGHT_SHARPNESS * (1.0 - HIGHLIGHT_DISPERSION);
        float expG = HIGHLIGHT_SHARPNESS;
        float expB = HIGHLIGHT_SHARPNESS * (1.0 + HIGHLIGHT_DISPERSION);

        vec3 specSpot = vec3(
            pow(refl1, expR),
            pow(refl1, expG),
            pow(refl1, expB)
        ) * spotMod * HIGHLIGHT_INTENSITY;

        // Edge bevel rim highlights
        float specRim1 = pow(refl2, 70.0) * 1.5;
        float specRim2 = pow(refl3, 70.0) * 1.3;
        float edgeGlint = fresnelPow * RIM_GLINT_INTENSITY;

        // Glass Fresnel transmission (Schlick approximation)
        float glassReflectance = 0.04 + 0.96 * fresnelPow;
        float glassTransmission = mix(1.0, glassReflectance, GLASS_TRANSPARENCY);

        // Material tints
        float mat = hitData.y;
        vec3 glassTint;
        float transFactor;

        if (mat == 2.0 || mat == 5.0) {
            // Beak & Feet: Translucent warm amber glass
            glassTint = BEAK_AMBER_TINT;
            transFactor = 0.55;
        } else if (mat == 3.0) {
            // Eye white: Crisp crystalline glass
            glassTint = EYE_WHITE_TINT;
            transFactor = 0.40;
        } else if (mat == 4.0) {
            // Pupil: Dark obsidian crystal with glossy glint
            glassTint = EYE_PUPIL_TINT;
            transFactor = 0.12;
        } else if (mat == 6.0) {
            // Chest/Belly: Lighter clear crystal patch
            glassTint = mix(CHEST_CRYSTAL_TINT, irid, 0.25);
            transFactor = glassTransmission * 0.85;
        } else {
            // Body, Wings, Tuft: Iconic Dash cyan glass with thin-film sheen
            vec3 cyanBase = mix(DASH_CYAN_TINT, irid, 0.30);
            glassTint = mix(irid, cyanBase, GLASS_TINT_INTENSITY);
            transFactor = glassTransmission;
        }

        // Shaded glass body with internal depth and transmission
        vec3 bodyColor = glassTint * (0.18 * diff1 + 0.05) * transFactor;

        // Edge rainbow rims
        vec3 edgeCol = vec3(
            edgeGlint * (0.7 + 0.4 * irid.r),
            edgeGlint * (0.8 + 0.3 * irid.g),
            edgeGlint * (1.0 + 0.2 * irid.b)
        );

        // Total specular composite with chromatic dispersion
        vec3 totalRim = (specRim1 + specRim2) * vec3(0.85, 0.92, 1.0);
        vec3 specCol = specSpot + totalRim;

        col = bodyColor + edgeCol + specCol;

        // Distance fade into background
        float fade = clamp((5.5 - t) / 2.0, 0.0, 1.0);
        col *= fade;
    } else {
        // Soft iridescent & Dash cyan corona in deep OLED black
        float glow = exp(-minD * CORONA_FALLOFF) * CORONA_BLOOM_GLOW;
        vec3 glowCol = spectralPalette(uv.x * 0.25 + uv.y * 0.20 - iTime * 0.2);
        vec3 dashGlow = DASH_CYAN_TINT;
        col = glow * mix(glowCol, dashGlow, 0.5);
    }

    // Filmic tone mapping & gamma correction
    col = acesFilm(col);
    col = pow(col, vec3(1.0 / 2.2));

    fragColor = vec4(col, 1.0);
}
